const state={lang:'zh' as Lang,light:false,page:'overview' as Page,view:'map',layout:'one',legendOpen:false,latestTab:'news' as 'news'|'meetings',catalog:'companies' as LayerId,catalogQuery:'',preset:'overview',active:[...presets.overview.layers],primary:'developers' as LayerId|null,inspect:presets.overview.inspect as LayerId|null,entity:null as Point|null,entityTabs:[] as Point[],hidden:[] as LayerId[],opacity:Object.fromEntries(layers.map(l=>[l.id,.88])) as Record<LayerId,number>,collapsed:new Set<string>(window.innerHeight>=850&&window.innerWidth>1100?['organizations','infrastructure','signals']:['organizations','projects','infrastructure','signals']),layerSearch:'',selected:'',grid:true,texture:'surface' as 'surface'|'points',mobile:'map',query:'',focus:false,topic:'all',portalQuery:'',supplyMetric:'models' as 'models'|'datasets',supplyMonth:'2026-09'};
