try{preferences=preferencesFrom(JSON.parse(localStorage.getItem('od:intelligence')??localStorage.getItem('od:preferences')??localStorage.getItem('od-review-prefs')??'{"demo":false}'));watch=JSON.parse(localStorage.getItem('od-review-watch')??'[]');state.light=JSON.parse(localStorage.getItem('od:light')??'false')===true;state.lang=localStorage.getItem('od:atlas-lang')==='en'?'en':'zh';}catch{}
