const icon=(id:string)=>{const p:Record<string,string>={map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15m6-12v15"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',wire:'<path d="M4 5h16M4 12h16M4 19h16M8 3v4m8 3v4m-5 3v4"/>',organizations:'<path d="M4 21V5h10v16M14 11h6v10M2 21h20M7 8h4M7 12h4M7 16h4M17 14v1m0 3v1"/>',projects:'<path d="M8 3H4v18h4m8-18h4v18h-4M10 8l-4 4 4 4m4-8 4 4-4 4"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',previous:'<path d="m15 5-7 7 7 7"/>',next:'<path d="m9 5 7 7-7 7"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 2 4v3"/>',assets:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6h1m-1 11h1m5-11h4m-4 11h4"/>',signal:'<path d="m2 12 5-1 3-7 4 16 3-8h5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',layers:'<path d="m12 3 10 6-10 6L2 9Zm-9 11 9 5 9-5"/>',pin:'<path d="M18 9c0 5-6 12-6 12S6 14 6 9a6 6 0 0 1 12 0Z"/><circle cx="12" cy="9" r="2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',expand:'<path d="M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 4v6h6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${p[id]??p.layers}</svg>`;};
const metricName=(key:string)=>state.lang==='en'?key:({'Report rank':'报告名次','Active developers':'活跃开发者','Active repositories':'活跃仓库','Participants':'参与者','Capacity (MW)':'装机容量（MW）','Primary fuel':'主要能源'} as Record<string,string>)[key]??key;
const layerColor=(id:LayerId)=>state.light?layerById[id].light:layerById[id].color;
const symbol=(id:LayerId)=>geometryIcon(layerById[id].kind,layerColor(id));
const activeAreas=()=>state.active.filter(isArea);
const activePoints=()=>mapSelection(state.active,state.primary,state.hidden).points;
const region=()=>regions.find(c=>c.rawCode===state.selected);
const regionLabel=()=>region()?countryName(region()!,state.lang):t('全球','World');
const actualEvents=():Event[]=>[...data.feed.events.filter(e=>e.provenance!=='demo'),...(data.located.layers.news??[]).map((p:any)=>({id:p.id,title:p.entityName[0],titleEn:p.entityName[1],summary:p.note[0],summaryEn:p.note[1],category:'research',severity:'info',occurredAt:p.period[0]+'T00:00:00Z',collectedAt:'2026-10-25T00:00:00Z',source:'LUMI / CSC',sourceUrl:p.sourceUrls[0],provenance:'manual',reviewStatus:'source-published',location:{name:p.countryZh,nameEn:p.country,lon:p.longitude,lat:p.latitude,countryCode:p.rawCode,precision:'city'},tags:['AI infrastructure']}))];
const relevantEvents=()=>actualEvents().filter(e=>(!state.selected||regionMatches(e.location?.countryCode,state.selected))&&(!state.query||`${e.title} ${e.titleEn??''} ${e.summary} ${e.source}`.toLowerCase().includes(state.query.toLowerCase()))).sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt));
function focusCountry(c:Country){state.selected=c.rawCode;state.entity=null;render();scene?.focus(c,Math.max(savedCamera?.zoom??1,1.2));}
function inspectLayer(id:LayerId){state.inspect=id;state.entity=null;if(isArea(id))state.primary=id;render();}
function inspectEntity(p:Point){if(state.focus){entityInfo(p);return;}const key=p.id??p.event?.id;if(!key)return;const entity={...p,id:key};if(!state.entityTabs.some(x=>x.id===key&&x.overlayId===p.overlayId))state.entityTabs.push(entity);state.inspect=p.overlayId;state.entity=entity;state.mobile='overview';render();}
function entityKey(p:Point){return `entity:${p.overlayId}:${p.id}`;}
function currentTab(){return state.entity?entityKey(state.entity):state.inspect?`layer:${state.inspect}`:'';}
function activateTab(key:string){if(key.startsWith('layer:'))inspectLayer(key.slice(6) as LayerId);else{const p=state.entityTabs.find(p=>entityKey(p)===key);if(p){state.entity=p;state.inspect=p.overlayId;render();}}}
function closeTab(key:string){const keys=[...state.active.map(id=>`layer:${id}`),...state.entityTabs.map(entityKey)],index=keys.indexOf(key),wasCurrent=currentTab()===key;if(key.startsWith('layer:')){state.active=state.active.filter(id=>`layer:${id}`!==key);state.hidden=state.hidden.filter(id=>state.active.includes(id));state.primary=reconcilePrimary(state.active,state.primary);state.preset='custom';soloSaved=null;}else state.entityTabs=state.entityTabs.filter(p=>entityKey(p)!==key);if(wasCurrent){const remaining=keys.filter(k=>k!==key),next=remaining[Math.min(index,remaining.length-1)];state.entity=next?.startsWith('entity:')?state.entityTabs.find(p=>entityKey(p)===next)??null:null;state.inspect=state.entity?.overlayId??(next?.startsWith('layer:')?next.slice(6) as LayerId:state.primary??state.active[0]??null);}render();}
function selectPoint(c:Country|Event|Event[]){if(Array.isArray(c)||'occurredAt'in c)return;const p=c as Point;if(p.overlayId){if(isBubble(p.overlayId)){state.inspect=p.overlayId;state.mobile='overview';focusCountry(p);return;}if(!isArea(p.overlayId)){if(p.clusterIds?.length){openCluster(p);return;}state.selected=regionGroup(p.rawCode);inspectEntity(p);return;}}focusCountry(c);}
function changeActive(next:LayerId[]){const added=next.find(id=>!state.active.includes(id));state.active=next;if(added){if(isArea(added))state.primary=added;state.inspect=added;}state.hidden=state.hidden.filter(x=>next.includes(x));state.primary=reconcilePrimary(next,state.primary);if(!state.inspect||!next.includes(state.inspect))state.inspect=state.primary??next[0]??null;state.entity=null;state.preset='custom';soloSaved=null;render();}
function applyPreset(id:string){const p=presets[id];if(!p)return;state.active=[...p.layers];state.hidden=[];state.primary=p.primary;state.inspect=p.inspect;state.entity=null;state.preset=id;soloSaved=null;render();}
function tree(){return groups.map(g=>{const matches=g.children.filter(id=>!state.layerSearch||tr(layerById[id].name).toLowerCase().includes(state.layerSearch.toLowerCase()));if(!matches.length)return '';const open=!state.collapsed.has(g.id)||!!state.layerSearch;return `<section class="tree-group"><div class="group-header"><button class="fold" data-fold="${g.id}" aria-expanded="${open}" aria-label="${t('展开或收起','Expand or collapse')} ${tr(g.name)}">${open?'⌄':'›'}</button>${g.exclusive?`<span class="exclusive-mark ${g.children.some(id=>state.active.includes(id))?'selected':''}" aria-hidden="true" title="${t('本组至多选一项；再次点击取消','Select up to one; click again to deselect')}"></span>`:`<input id="group-${g.id}" data-group="${g.id}" type="checkbox" aria-label="${t('选择整组','Select group')} ${tr(g.name)}" ${groupState(g.children,state.active)==='all'?'checked':''}/>`}<span class="group-icon">${icon(g.icon)}</span><button class="group-name" data-fold="${g.id}">${tr(g.name)}</button><small>${g.exclusive?t('0–1 项','0–1'):g.children.length}</small></div>${open?`<ul>${matches.map(id=>`<li class="layer-row ${state.active.includes(id)?'selected':''} ${state.primary===id?'is-primary':''}"><label title="${tr(layerById[id].metric)}"><input id="layer-${id}" data-layer="${id}" type="checkbox" class="${g.exclusive?'optional-single':''}" ${state.active.includes(id)?'checked':''}/>${symbol(id)}<span>${tr(layerById[id].name)}</span></label><span class="geometry-tag" data-geometry="${layerById[id].kind}" title="${isArea(id)?t('地域统计色块','Regional choropleth'):isBubble(id)?t('地域资产数量 · 气泡面积编码','Regional asset quantity · proportional area'):t('实体坐标圆点','Located entity circles')}">${isArea(id)?t('面','AREA'):isBubble(id)?t('泡','BUBBLE'):t('点','POINT')}</span>${state.primary===id?`<span class="primary-tag">${t('主','MAP')}</span>`:layerById[id].demo?`<span class="demo-dot" title="${t('固定示范实体','Fixed fictional entities')}">◌</span>`:''}<button class="layer-info" data-info="${id}" aria-label="${tr(layerById[id].name)} · ${t('范围说明','Scope')}">i</button></li>`).join('')}</ul>`:''}</section>`;}).join('')||`<div class="empty">${t('没有匹配图层','No matching layer')}</div>`;}
function bubbleOrderHint(){return `<span class="bubble-order" title="${t('气泡始终位于实体圆点下方','Bubbles render below entity points')}">${geometryIcon('bubble')}</span>`;}
function stack(){const ids=state.active.filter(id=>!isArea(id));return `<div class="stack-title"><div><span class="eyebrow">${t('显示管理','DISPLAY')}</span><b>${state.active.length}</b></div><button id="clear-layers">${t('清空','Clear')}</button></div>${activeAreas().length?`<div class="area-tabs">${activeAreas().map(id=>`<button data-inspect="${id}" class="${state.primary===id?'active':''}" aria-pressed="${state.primary===id}">${symbol(id)}${tr(layerById[id].name)}</button>`).join('')}</div>`:''}<div class="stack-list">${[...ids].reverse().map(id=>`<div class="stack-item ${state.hidden.includes(id)?'hidden-layer':''}"><div>${symbol(id)}<span>${tr(layerById[id].name)}</span><button data-solo="${id}" aria-pressed="${soloSaved!==null&&!state.hidden.includes(id)}" title="${t('独显点层／恢复','Isolate points / restore')}" aria-label="${t('独显','Isolate')} ${tr(layerById[id].name)}">◎</button>${!isBubble(id)?`<button data-up="${id}" ${id===state.active.filter(k=>!isRegional(k)).at(-1)?'disabled':''} aria-label="${t('上移','Move up')} ${tr(layerById[id].name)}">↑</button>`:bubbleOrderHint()}<button data-eye="${id}" aria-label="${t('显示或隐藏','Show or hide')} ${tr(layerById[id].name)}" aria-pressed="${!state.hidden.includes(id)}">${icon('eye')}</button></div><label class="opacity-control"><input type="range" min="10" max="100" value="${Math.round(state.opacity[id]*100)}" data-opacity="${id}" aria-label="${tr(layerById[id].name)} ${t('透明度','opacity')}"/><output>${Math.round(state.opacity[id]*100)}%</output></label></div>`).join('')}</div>${!state.active.length?`<p class="stack-empty">${t('勾选图层开始观察','Select layers to begin')}</p>`:''}`;}
function globalOverview(){const d=dashboard.upstream.summary;const cards=[['regions',t('地域覆盖','Regions'),d.totalCountries,t('国家和地区','Countries & territories')],['developers',t('开发者总量','Developers'),d.totalDevelopers,t('累计参与基础','Developer population')],['repositories',t('仓库总量','Repositories'),d.totalRepos,t('全域仓库记录','Repository records')],['logs',t('日志总量','Event logs'),d.totalRecords,t('生态活动记录','Activity records')],['intelligence',t('资讯总量','Intelligence'),dashboard.intelligence.value,t('模拟规模','Simulated inventory')]];return `<section class="coverage-ribbon panel" aria-label="${t('全球数据概览','Global coverage')}"><div class="coverage-metrics">${cards.map(([id,label,value,note])=>`<div class="coverage-metric" title="${esc(String(label))} · ${fmt(Number(value))} · ${esc(String(note))}"><span>${label}${id==='intelligence'?` <i>${t('模拟','DEMO')}</i>`:''}</span><strong data-stat="${id}">${short(value as number)}</strong><small>${note}</small></div>`).join('')}</div></section>`;}
function scopePanel(){const visible=mapSelection(state.active,state.primary,state.hidden);const pointLayers=visible.points.filter(id=>!isBubble(id)),located=pointLayers.reduce((n,id)=>n+scopedPoints(id,data,state.selected).length,0);const encodings=Number(!!state.primary)+Number(visible.points.some(isBubble))+Number(pointLayers.length>0);return `<section class="scope-panel panel"><div class="scope-title"><span>${t('当前观察','CURRENT OBSERVATION')}</span>${state.selected?`<button id="clear-region">${t('返回全球','Reset')} ↗</button>`:''}</div><h2>${icon('pin')}${esc(regionLabel())}</h2><div class="scope-stats"><span><b>${state.active.length}</b> ${t('图层','layers')}</span><span><b>${encodings}</b> ${t('种表达','encodings')}</span><span><b>${located}</b> ${t('定位实体','located entities')}</span></div></section>`;}
function latestPanel(){const news=actualEvents().sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt));const meetings=[...pointIndex.meetings].sort((a,b)=>{const date=(p:Point)=>Date.parse(p.period?.[0].slice(0,10)??'');const now=Date.parse(dashboard.checkedAt);return (date(a)>=now?0:1)-(date(b)>=now?0:1)||Math.abs(date(a)-now)-Math.abs(date(b)-now);});const translated:Record<string,string>={'758d87a72c9122fd8766':'OpenSSF：上游贡献如何减少技术债','b9392c7f7addad4be81c':'CNCF：多租户 GPU Kubernetes 实践'};return `<section class="latest-panel panel" aria-label="${t('最新资讯','Latest intelligence')}"><header><h2>${t('最新资讯','Latest')}</h2><div role="tablist" aria-label="${t('资讯类型','Intelligence type')}">${(['news','meetings'] as const).map(k=>`<button role="tab" id="latest-tab-${k}" aria-controls="latest-content" aria-selected="${state.latestTab===k}" tabindex="${state.latestTab===k?0:-1}" data-latest-tab="${k}">${k==='news'?t('新闻','News'):t('活动','Events')}</button>`).join('')}</div><small>${t('快照','SNAPSHOT')}</small></header><div id="latest-content" role="tabpanel" aria-labelledby="latest-tab-${state.latestTab}" tabindex="0">${state.latestTab==='news'?news.slice(0,2).map(e=>`<button class="latest-row" data-event="${esc(e.id)}" title="${esc(e.title)}"><time>${new Date(e.occurredAt).toLocaleDateString('en-US',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'})}</time><span><b>${esc(state.lang==='zh'?translated[e.id]??e.title:e.titleEn??e.title)}</b><small>${esc(e.source)}</small></span><i>↗</i></button>`).join(''):meetings.slice(0,2).map(p=>`<button class="latest-row" data-meeting="${esc(p.id)}" title="${esc(tr(p.entityName!))}"><time>${p.period?.[0].slice(5,10).replace('-','/')}</time><span><b>${esc(tr(p.entityName!))}</b><small>${esc(countryName(p,state.lang))} · ${Date.parse(p.period?.[0].slice(0,10)??'')>=Date.parse(dashboard.checkedAt)?t('即将举办','Upcoming'):t('已举办','Past event')}</small></span><i>↗</i></button>`).join('')}</div></section>`;}
function valueFor(id:LayerId){if(!state.selected)return layerTotal(id,data);if(isRegional(id))return pointIndex[id].find(p=>p.rawCode===state.selected)?.atlasValue;return scopedPoints(id,data,state.selected).length;}
function totalScope(id:LayerId){if(state.selected)return t('所选地域','Selected region');if(id==='developers')return t('报告全球活跃','Report global active');if(isRegional(id))return data.report.areas[id]?tr(data.report.areas[id].scope):t('已收录地域','Observed regions');const cat=data.report.catalogs[id];return cat?`${t('已定位','Located')} ${pointIndex[id].length} / ${cat.rows.length} ${t('原表条目','report records')}`:t('已定位样本','Located sample');}

function comparison(){
 const id=state.inspect,active=currentTab();
 const tabs=[...state.active.map(k=>({key:`layer:${k}`,name:tr(layerById[k].name),layer:k,entity:false})),...state.entityTabs.map(p=>({key:entityKey(p),name:p.entityName?tr(p.entityName):p.event?.title??p.country,layer:p.overlayId,entity:true}))];
 return `<section class="compare-panel tabbed-inspector panel ${!state.entity&&id&&rankingRows(id,data).length?'has-ranking':''}">
 <div class="inspector-tabs" role="tablist" aria-label="${t('图层与实体标签页','Layer and entity tabs')}">${tabs.map((tab,i)=>`<div class="inspector-tab ${tab.key===active?'active':''}" style="--tone:${layerColor(tab.layer)}"><button id="inspect-tab-${i}" role="tab" tabindex="${tab.key===active?'0':'-1'}" aria-selected="${tab.key===active}" aria-controls="observation-panel" data-observation-tab="${esc(tab.key)}" title="${esc(tab.name)}">${tab.entity?'<span class="entity-tab-icon">↗</span>':symbol(tab.layer)}<span>${esc(tab.name)}</span></button><button data-close-tab="${esc(tab.key)}" aria-label="${t('关闭','Close')} ${esc(tab.name)}" title="${tab.entity?t('关闭实体标签','Close entity tab'):t('关闭标签并取消图层','Close tab and deselect layer')}">×</button></div>`).join('')}</div>
 <div id="observation-panel" class="inspector-body ${!state.entity&&id&&rankingRows(id,data).length?'is-ranking':''}" role="tabpanel" tabindex="0" ${tabs.length?`aria-labelledby="inspect-tab-${Math.max(0,tabs.findIndex(tab=>tab.key===active))}"`:''}>${state.entity?entityPanel(state.entity):id?layerPanel(id):`<div class="inspector-empty">${icon('layers')}<b>${t('自由组合你的观察','Build your own observation')}</b><p>${t('选择一个或多个图层。开发者与资产组也可以不选。','Choose one or more layers. Developer and asset groups may be left empty.')}</p></div>`}</div>
 </section>`;
}
function rankList(id:LayerId){const rows=rankingRows(id,data);const max=Math.max(1,...rows.map(r=>r.value));return rows.slice(0,10).map(r=>`<button class="inspector-rank ${r.region?.rawCode===state.selected?'selected':''}" data-rank-key="${esc(r.key)}" data-rank-layer="${id}" title="${esc(r.region?countryName(r.region,state.lang):tr(r.name))}"><span class="rank-number">${String(r.rank).padStart(2,'0')}</span><span class="rank-name"><b>${esc(r.region?countryName(r.region,state.lang):tr(r.name))}</b><i style="--bar:${r.value/max*100}%;--tone:${layerColor(id)}"></i></span><strong>${short(r.value)}</strong><span class="rank-arrow">${r.entity?'↗':'›'}</span></button>`).join('');}
function layerPanel(id:LayerId){
 const l=layerById[id],cat=id==='code'?data.repoRanking:data.report.catalogs[id],rows=rankingRows(id,data),regional=isRegional(id),isCode=id==='code';
 const count=cat?cat.rows.length:pointIndex[id].length;
 const period=cat?tr(cat.period):tr(l.scope);
 return `<div class="inspector-summary"><div class="inspector-title"><span>${symbol(id)}<b>${tr(l.name)}</b></span><button data-info="${id}" aria-label="${t('指标口径','Metric scope')}">ⓘ</button></div>
 <div class="inspector-value"><strong>${cat?fmt(count):short(valueFor(id))}</strong><span>${cat?t('条榜单记录','ranked records'):tr(l.unit)}</span><small>${!cat?totalScope(id):isCode?t('月度榜','Monthly'):t('报告原表','Report table')}</small></div>
 <p class="inspector-period" title="${esc(period)}">${esc(period)}</p>
 ${regional&&state.selected&&cat?`<div class="region-observation">${esc(regionLabel())} · ${valueFor(id)==null?t('数量未收录','Quantity unavailable'):fmt(valueFor(id))}</div>`:''}
 ${regional&&!pointIndex[id].length?`<button data-info="${id}" class="inspector-gap">${t('地域数量待补 · 暂无气泡分布','Regional counts pending · no bubbles')} ⓘ</button>`:''}
 </div>
 ${rows.length?`<div class="rank-heading"><b>${cat?t('全球前十','Global top 10'):t('地域前十','Regional top 10')}</b><span>${cat?(id==='llm'?'ModelRank':'OpenRank'):tr(l.unit)}</span></div><div class="inspector-ranks">${rankList(id)}</div>`:regional?`<div class="inspector-empty compact"><p>${t('等待可追溯的观测数据','Awaiting traceable observations')}</p></div>`:`<div class="inspector-entities">${scopedPoints(id,data,state.selected).map(p=>`<button data-entity="${esc(p.id??p.event?.id)}">${symbol(id)}<span><b>${esc(p.entityName?tr(p.entityName):p.event?.title??countryName(p,state.lang))}</b><small>${esc(countryName(p,state.lang))}</small></span>↗</button>`).join('')||`<p class="empty">${t('当前地域暂无已定位样本','No located samples in this region')}</p>`}</div>`}
 <button class="catalog-link" data-open-catalog="${id}"><span>${t('完整清单与口径','Full catalog & scope')}</span><b>${rows.length||count} ↗</b></button>`;
}
function entityPanel(p:Point){const located=p.longitude!=null&&p.latitude!=null;return `<div class="inspector-title"><span>${symbol(p.overlayId)}<b>${tr(layerById[p.overlayId].name)}</b></span><button data-back-layer="${p.overlayId}">${t('图层','Layer')} ↶</button></div><h3 class="entity-title">${esc(p.entityName?tr(p.entityName):p.event?.title??p.country)}</h3><p class="inspector-period">${esc(p.period?tr(p.period):p.event?.occurredAt?.slice(0,10)??'')}</p><div class="entity-metrics">${p.metrics?.map(([k,v])=>`<div><span>${esc(metricName(k))}</span><b>${typeof v==='number'?fmt(v):esc(v)}</b></div>`).join('')??''}</div><div class="entity-location"><span>${icon('pin')}${located?esc(countryName(p,state.lang)):t('位置待核验','Location unverified')}</span><small>${located?esc(p.locationRole?tr(p.locationRole):t('事件地点','Event location')):t('保留榜单记录，不猜测坐标','Listed record; no inferred coordinates')}</small></div><p class="entity-note">${esc(p.note?tr(p.note):p.event?.summary??'')}</p><div class="entity-actions">${located?`<button class="primary" data-locate-tab>${t('在地图中定位','Locate on map')}</button>`:''}<button data-entity-evidence>${t('查看证据与详情','Evidence & details')} ↗</button></div>`;}
function eventCards(events:Event[],limit=2){return events.slice(0,limit).map(e=>`<button class="event-card" data-event="${esc(e.id)}"><div><span class="event-kind">${e.category==='release'?t('版本发布','RELEASE'):e.category==='security'?t('安全','SECURITY'):t('生态动态','ECOSYSTEM')}</span><time>${new Date(e.occurredAt).toLocaleDateString(state.lang==='zh'?'zh-CN':'en-GB',{month:'2-digit',day:'2-digit'})}</time></div><h3>${esc(state.lang==='en'?e.titleEn??e.title:e.title)}</h3><p>${esc(e.source)} <span>↗</span></p></button>`).join('');}
function wire(){const ev=relevantEvents();return `<div class="wire-view"><div class="wire-title"><span class="eyebrow">ECOSYSTEM WIRE</span><h1>${t('全球生态快讯','Ecosystem wire')}</h1><p>${t('已发布内容快照 · 未定位事件保留在全球列表','Published snapshot · unlocated events remain in the global list')} · ${esc(regionLabel())}${state.selected?` <button data-action="clear-region">${t('查看全球','Show global')}</button>`:''}</p></div><div class="wire-search">${icon('search')}<input id="wire-query" value="${esc(state.query)}" placeholder="${t('搜索项目、主题或来源','Search projects, topics or sources')}" aria-label="${t('搜索快讯','Search wire')}"/><span>${ev.length}</span></div><div class="wire-cards">${ev.length?eventCards(ev,100):`<p class="empty">${t('当前范围没有匹配事件。','No matching events in this scope.')}</p>`}</div></div>`;}
function legend(){const id=state.primary,assets=activePoints().find(isBubble),points=activePoints().filter(k=>!isBubble(k)),max=id?Math.max(1,...pointIndex[id].map(p=>p.atlasValue??0)):0;return `<button id="legend-toggle" class="legend-toggle" aria-expanded="${state.legendOpen}" aria-controls="legend-content" title="${t('展开或收起图例','Expand or collapse legend')}">${icon('layers')}<b>${t('图例','Legend')}</b><span>${id?'1':'0'} ${t('面','area')} · ${assets?'1':'0'} ${t('泡','bubble')} · ${points.length} ${t('点','points')}</span><i>${state.legendOpen?'⌄':'⌃'}</i></button><div id="legend-content" ${state.legendOpen?'':'hidden'}>${id&&pointIndex[id].length?`<div class="compact-fill"><button data-info="${id}">${symbol(id)}${tr(layerById[id].name)}</button><span>${tr(layerById[id].unit)}</span><div class="color-ramp" style="--ramp:${legendRamp(id,state.light)}"></div><small>0</small><small>${t('对数色阶 · 灰色未收录','Log · gray not observed')}</small><small>${short(max)}</small></div>`:`<p class="compact-no-fill">${t('地理底图 · 未选面指标','Basemap · no area metric')}</p>`}${bubbleLegend()}${points.length?`<div class="compact-points">${points.map(k=>`<button data-inspect="${k}">${symbol(k)}${tr(layerById[k].name)}</button>`).join('')}</div>`:''}</div>`;}
function bubbleLegend(){const id=activePoints().find(isBubble);if(!id)return '';const max=Math.max(0,...pointIndex[id].map(p=>p.atlasValue??0));return `<div class="compact-bubble" style="--bubble-color:${layerColor(id)}"><button data-info="${id}">${symbol(id)}${tr(layerById[id].name)}</button>${max?`<span class="bubble-mini-key" aria-hidden="true"><i></i><i></i><i></i></span><small>${t('面积 ∝ 数量','Area ∝ count')}</small>`:`<small>${t('地域数量待补','Counts pending')}</small>`}</div>`;}
function header(){return `<header class="topbar"><div class="brand-pair"><img class="lab-logo" src="./brand/XlabAI_WordmarkCompact_Color${state.light?'Light':'Dark'}.svg" alt="X-lab AI"/><i></i><a href="#overview" data-page="overview"><img class="product-logo" src="./brand/opendipper/opendipper-horizontal-${state.light?'light':'dark'}.svg" alt="开源北斗 OpenDipper"/></a></div><nav class="product-nav" aria-label="${t('主导航','Main navigation')}">${(['overview','radar','ecosystem','briefing','contribute'] as Page[]).map(id=>`<button data-page="${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${pages[id][state.lang]}</button>`).join('')}</nav><div class="top-actions"><button data-page="following" aria-label="${t('我的关注','My watchlist')}">☆</button>${state.page==='overview'||state.page==='radar'||state.page==='ecosystem'?`<div class="layout-switch" aria-label="${t('演示布局','Presentation layout')}"><button data-layout="one" aria-pressed="${state.layout==='one'}" class="${state.layout==='one'?'active':''}">${t('一屏','One')}</button><button data-layout="two" aria-pressed="${state.layout==='two'}" class="${state.layout==='two'?'active':''}">${t('两屏','Two')}</button></div>`:''}<button data-action="fullscreen" class="fullscreen-button" aria-pressed="${!!document.fullscreenElement}">${t(document.fullscreenElement?'退出全屏':'全屏',document.fullscreenElement?'Exit full':'Full screen')}</button>${state.page==='overview'||state.page==='radar'||state.page==='ecosystem'?'':`<button data-action="sources" class="sources-button">${t('数据与来源','Sources')}</button>`}<button id="language-toggle" data-action="language" aria-label="${t('Switch to English','切换中文')}">${state.lang==='zh'?'EN':'中'}</button><button id="theme-toggle" data-action="theme" class="icon-button" aria-label="${t('切换明暗主题','Toggle theme')}" title="${state.light?t('切换深色模式','Switch to dark theme'):t('切换浅色模式','Switch to light theme')}" aria-pressed="${state.light}">${icon('sun')}</button><a class="repo-link" href="https://github.com/X-lab2017/open-dipper" target="_blank" rel="noopener" aria-label="GitHub ${t('项目仓库','repository')}" title="GitHub">↗</a></div></header>`;}
function contextbar(){return `<div class="contextbar"><nav class="view-nav od-segmented" aria-label="${t('空间视图','Spatial views')}">${[['map','全球地图','Map'],['globe','立体地球','Globe']].map(([id,z,en])=>`<button data-view="${id}" class="${state.view===id?'active':''}" aria-pressed="${state.view===id}">${icon(id)}<span>${t(z,en)}</span></button>`).join('')}</nav><button class="source-stamp" data-action="sources" title="${t('本页数据核对日期；上游快照为','Page verification date; source snapshot:')} ${dashboard.upstream.summary.updatedAt.slice(0,10)}"><span>${t('数据来源','DATA SOURCE')}</span><img src="./brand/opendigger/icon.png" alt=""/><b>OpenDigger</b><i></i><span>${t('数据更新','UPDATED')}</span><time datetime="${dashboard.checkedAt}">${dashboard.checkedAt}</time><i></i><span class="source-details">${t('口径与来源','Scope & sources')} ⓘ</span></button><div class="context-actions"><div class="perspective"><label for="perspective">${t('观测视角','Perspective')}</label><select id="perspective" title="${state.preset==='custom'?t('自定义图层组合','Custom layer combination'):tr(presets[state.preset].description)}">${Object.entries(presets).map(([id,p])=>`<option value="${id}" ${state.preset===id?'selected':''}>${tr(p.name)}</option>`).join('')}${state.preset==='custom'?`<option selected value="custom">${t('自定义组合','Custom')}</option>`:''}</select></div><button class="help-button" data-action="help" aria-label="${t('使用指南','How to use')}" title="${t('使用指南','How to use')}">?</button></div></div>`;}
function mapPanel(){return `<main class="map-panel panel" aria-label="${t('全球开放生态','Global open ecosystem')}"><div class="map-container"><canvas id="earth" tabindex="0" aria-label="${t('交互地图，可拖拽、缩放；点击地域或圆点查看数据','Interactive map; drag, zoom, select regions or circles')}" role="img"></canvas><div class="map-return" ${state.focus?'':'hidden'}><button data-action="map-fullscreen">← ${t('返回观测台','Back to observatory')} <kbd>Esc</kbd></button><span>${state.view==='globe'?t('立体地球','Globe'):t('全球地图','Map')}</span></div><div class="map-topline"><span class="map-caption">${tour.active?`${String(tour.index+1).padStart(2,'0')} / 05 · ${tr(layerById[tourStops[tour.index].layer].name)}`:state.selected?esc(regionLabel()):state.primary?tr(layerById[state.primary].name):t('观测地图','Observation map')}</span><span class="map-pulse-label" hidden>${t('◌ 模拟动态','◌ SIMULATED PULSES')}</span></div><button class="locate-button" data-action="regions">${icon('search')}${t('查找地域','Find a region')}<kbd>⌘ K</kbd></button>${activeAreas().length>1?`<select class="map-fill-select" id="primary-layer" aria-label="${t('切换地图色阶','Switch map fill')}" title="${t('切换地图色阶','Switch map fill')}">${activeAreas().map(id=>`<option value="${id}" ${state.primary===id?'selected':''}>${tr(layerById[id].name)}</option>`).join('')}</select>`:''}<div class="map-tools"><button data-action="zoom-in" aria-label="${t('放大','Zoom in')}">+</button><button data-action="zoom-out" aria-label="${t('缩小','Zoom out')}">−</button><button id="map-fullscreen-button" data-action="map-fullscreen" aria-label="${t(state.focus?'退出地图全屏':'全屏地图',state.focus?'Exit map fullscreen':'Fullscreen map')}" aria-pressed="${state.focus}" title="${t(state.focus?'返回观测台（Esc）':'全屏地图',state.focus?'Back to observatory (Esc)':'Fullscreen map')}">${icon(state.focus?'close':'expand')}</button><span></span><button data-action="reset" aria-label="${t('重置地图','Reset map')}">${icon('reset')}</button><button data-action="grid" class="${state.grid?'active':''}" aria-label="${t('显示经纬网','Toggle graticule')}" aria-pressed="${state.grid}">⌗</button>${state.view==='globe'?`<button data-action="rotate" aria-label="${t('旋转地球','Rotate globe')}">↻</button>`:''}</div><div id="scene-tooltip" class="scene-tooltip" hidden></div><div class="map-legend ${state.legendOpen?'expanded':'collapsed'}">${legend()}</div><div id="camera-readout" class="camera-readout"></div></div><div class="map-footer ${tour.active?'tour-active':''}">${state.layout==='two'&&!state.focus?`<button data-scroll-screen="2" class="screen-jump">02 ${t('清单与快讯','Catalog & wire')} ↓</button>`:''}<div class="map-navigation">${[['world','全球','World'],['asia','亚洲','Asia'],['europe','欧洲','Europe'],['americas','美洲','Americas'],['africa','非洲','Africa']].map(([id,z,e])=>`<button data-zone="${id}">${t(z,e)}</button>`).join('')}</div><div id="tour-dock">${tourControls()}</div></div></main>`;}
function centralStage(){return `<section class="center-stage" aria-label="${t('全球观测主画面','Global observatory stage')}">${globalOverview()}${mapPanel()}${pulseMarkup(state.lang,dashboard)}</section>`;}
function observatory(){return `${contextbar()}<div class="mobile-tabs">${[['map','地图','Map'],['layers','图层','Layers'],['overview','概览','Overview']].map(([id,z,en])=>`<button data-mobile="${id}" aria-pressed="${state.mobile===id}" class="${state.mobile===id?'active':''}">${t(z,en)}</button>`).join('')}</div><div class="workspace"><aside class="left-panel panel"><div class="panel-heading"><h2>${icon('layers')}${t('观测图层','Observation layers')}</h2><span>${layers.length} ${t('图层','layers')}</span></div><div class="tree-search">${icon('search')}<input id="layer-search" value="${esc(state.layerSearch)}" placeholder="${t('搜索观测对象','Find a layer')}" aria-label="${t('搜索图层','Search layers')}"/><kbd>/</kbd></div><div class="tree-key"><span>${geometryIcon('area')}${t('面 · 指标','Area · metric')}</span><span>${geometryIcon('bubble')}${t('泡 · 数量','Bubble · count')}</span><span>${geometryIcon('point')}${t('点 · 位置','Point · location')}</span></div><div class="tree-scroll">${tree()}</div><div class="layer-stack">${stack()}</div></aside>${centralStage()}<aside class="right-panel">${scopePanel()}${comparison()}${latestPanel()}</aside></div>`;}
function catalogRows(id:LayerId){
 const q=state.catalogQuery.toLowerCase();
 if(isRegional(id)&&id!=='code')return pointIndex[id].filter(p=>`${p.country} ${p.countryZh} ${p.rawCode}`.toLowerCase().includes(q)).sort((a,b)=>(b.atlasValue??0)-(a.atlasValue??0)).map(p=>`<button class="catalog-row" data-catalog-region="${id}" data-region="${p.rawCode}"><span>${esc(countryName(p,state.lang))}<small>${esc(p.rawCode)}</small></span><strong>${fmt(p.atlasValue)}</strong><em>${tr(layerById[id].unit)}</em></button>`).join('')||`<div class="catalog-empty"><b>${t('地域数据待共建','Regional observations needed')}</b><p>${esc(sourceText(id,state.lang,data))}</p></div>`;
 const cat=id==='code'?data.repoRanking:data.report.catalogs[id];
 if(cat)return cat.rows.filter((r:any)=>JSON.stringify(r).toLowerCase().includes(q)).map((r:any)=>{const name=r.name_zh||r.name||r.company_zh||r.foundation_zh||r.project||r.model_id;const en=r.name||r.company||r.foundation||r.project||r.model_id;const p=pointIndex[id].find(p=>p.entityName?.includes(en)||(en==='Stichting NixOS Foundation'&&p.id==='nixos-foundation'));return `<div class="catalog-row ${p?'located':'unlocated'}"><span><small>#${esc(r.rank)} · ${p?t('已定位','Located'):t('位置待核验','Location pending')}</small><b>${esc(state.lang==='en'?en:name)}</b></span><strong>${short(Number(r.openrank??r.modelrank_value))}<small>${id==='llm'?'ModelRank':'OpenRank'}</small></strong>${p?`<button data-entity="${esc(p.id)}" aria-label="${t('查看','Inspect')} ${esc(name)}">↗</button>`:`<a href="${esc(cat.sourceUrl)}" target="_blank" rel="noopener" aria-label="${t('原表','Source table')} ${esc(name)}">↗</a>`}</div>`;}).join('')||`<p class="empty">${t('没有匹配条目','No matching records')}</p>`;
 return pointIndex[id].filter(p=>JSON.stringify(p.entityName??[p.country,p.event?.title]).toLowerCase().includes(q)).map(p=>`<button class="catalog-row located" data-entity="${esc(p.id)}"><span><small>${esc(p.period?tr(p.period):'')}</small><b>${esc(p.entityName?tr(p.entityName):p.event?.title??p.country)}</b></span><em>${esc(countryName(p,state.lang))}</em>↗</button>`).join('')||`<p class="empty">${t('没有匹配条目','No matching records')}</p>`;
}
function secondScreen(){return `<section id="screen-two" class="evidence-screen"><header class="screen-heading"><div><span class="eyebrow">02 / EVIDENCE & SIGNALS</span><h1>${t('从空间分布，到具体对象','From spatial patterns to real entities')}</h1><p>${t('原表清单、位置证据与已发布快讯，分别阅读。','Report catalogs, location evidence and published news, kept in context.')}</p></div><button data-scroll-screen="1">↑ ${t('返回地图','Back to map')}</button></header><div class="evidence-grid"><section class="catalog-panel panel"><div class="catalog-heading"><h2>${t('观测对象清单','Observation catalog')}</h2><select id="catalog-layer" aria-label="${t('清单图层','Catalog layer')}">${groups.map(g=>`<optgroup label="${tr(g.name)}">${g.children.map(id=>`<option value="${id}" ${state.catalog===id?'selected':''}>${tr(layerById[id].name)}</option>`).join('')}</optgroup>`).join('')}</select></div><p class="catalog-scope">${state.catalog==='code'?tr(data.repoRanking.period):tr(layerById[state.catalog].scope)} · ${t('全球清单','Global catalog')}</p><input id="catalog-query" value="${esc(state.catalogQuery)}" placeholder="${t('搜索名称、组织或地域','Search names, organizations or regions')}" aria-label="${t('搜索清单','Search catalog')}"/><div class="catalog-scroll">${catalogRows(state.catalog)}</div><p class="catalog-foot">${t('未定位不等于不存在；圆点位置不代表全部贡献来源。','Unlocated does not mean absent. A point does not represent all contribution origins.')}</p></section><section class="wire-panel panel">${wire()}</section></div></section>`;}
function openCatalog(id:LayerId){state.catalog=id;state.catalogQuery='';if(state.layout==='two'){render();document.querySelector('#screen-two')?.scrollIntoView({behavior:'smooth'});return;}modal(`${tr(layerById[id].name)} · ${t('数据清单','Catalog')}`,`<p>${id==='code'?tr(data.repoRanking.period):tr(layerById[id].scope)} · ${totalScope(id)}</p><div class="modal-catalog">${catalogRows(id)}</div>`);document.querySelectorAll<HTMLElement>('.modal [data-entity]').forEach(el=>el.onclick=()=>{const p=pointIndex[id].find(p=>p.id===el.dataset.entity);if(p)inspectEntity(p);});document.querySelectorAll<HTMLElement>('.modal [data-region]').forEach(el=>el.onclick=()=>{const c=regions.find(c=>c.rawCode===el.dataset.region);if(c){if(!state.active.includes(id))state.active=toggleLayer(state.active,id);if(isArea(id))state.primary=id;state.inspect=id;focusCountry(c);}});}
async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast(t('当前浏览器不支持全屏，请使用浏览器的全屏功能。','Fullscreen is unavailable here; use your browser fullscreen control.'));}catch{toast(t('当前浏览器未允许全屏，可使用浏览器全屏功能。','Fullscreen was not allowed; use browser fullscreen instead.'));}}
async function exitMapFullscreen(){
 state.focus=false;
 // Escape may arrive before requestFullscreen resolves. Finish that request before exiting.
 try{await mapFullscreenRequest;}catch{}
 const exitNative=mapOwnsFullscreen&&!!document.fullscreenElement;mapOwnsFullscreen=false;
 if(exitNative)try{await document.exitFullscreen();}catch{}
 render();document.querySelector<HTMLElement>('#map-fullscreen-button')?.focus({preventScroll:true});
}
async function toggleMapFullscreen(){
 if(state.focus){await exitMapFullscreen();return;}
 state.focus=true;state.mobile='map';render();document.querySelector<HTMLElement>('.map-return button')?.focus({preventScroll:true});
 if(!document.fullscreenElement&&document.documentElement.requestFullscreen){
  mapOwnsFullscreen=true;
  try{mapFullscreenRequest=document.documentElement.requestFullscreen();await mapFullscreenRequest;}catch{mapOwnsFullscreen=false;toast(t('已展开全窗口地图；浏览器未允许隐藏窗口边框。可点“返回观测台”退出。','Map expanded to the window; browser fullscreen was not allowed. Use Back to observatory to return.'));}finally{mapFullscreenRequest=undefined;}
 }
}
document.addEventListener('fullscreenchange',()=>{
 if(!document.fullscreenElement&&mapOwnsFullscreen){mapOwnsFullscreen=false;if(state.focus){state.focus=false;render();document.querySelector<HTMLElement>('#map-fullscreen-button')?.focus({preventScroll:true});}}
 const b=document.querySelector<HTMLElement>('[data-action="fullscreen"]');if(b){b.textContent=t(document.fullscreenElement?'退出全屏':'全屏',document.fullscreenElement?'Exit full':'Full screen');b.setAttribute('aria-pressed',String(!!document.fullscreenElement));}
});


function portalContext():PortalContext{return {lang:state.lang,page:state.page,signals:signalsFor(actualEvents(),data.intelligence,preferences.demo),preferences,data:{snapshot:data.snapshot,feed:data.feed,features:data.features,geography:{fetchedAt:'',layers:[]},demo:{generatedAt:'',countries:[],events:[]}} as Data,watch,topic:state.topic,query:state.portalQuery,fixtureAvailable:!!data.intelligence,evidence:data.evidence,supplyMetric:state.supplyMetric,supplyMonth:state.supplyMonth};}
function ecosystem(){return `<div class="repository-grid">${data.snapshot.repositories.map((r:any)=>{const p=r.metrics.openrank?.points.at(-1);return `<button class="repository-card" data-project="${esc(r.path)}"><span>${esc(r.platform)} · ${p?.month??'—'}</span><h3>${esc(r.path)}</h3><strong>${fmt(p?.value)}</strong><small>OpenRank ↗</small></button>`;}).join('')}</div>`;}

function tourWorkspace(){return {active:[...state.active],hidden:[...state.hidden],primary:state.primary,inspect:state.inspect,entity:state.entity,entityTabs:[...state.entityTabs],selected:state.selected,preset:state.preset,view:state.view,mobile:state.mobile};}
let beforeTour:{workspace:ReturnType<typeof tourWorkspace>;camera:ReturnType<Scene['camera']>|undefined;solo:LayerId[]|null}|undefined;
const tourMotion=matchMedia('(prefers-reduced-motion: reduce)');
const tour=new ObservatoryTour(showTourStop,updateTourControls);
function tourControls(){
 if(!tour.active)return `<button id="tour-start" data-tour="start" title="${t('五站巡航：开发者、企业、项目、模型与活动','Five stops: developers, companies, projects, models and events')}">${icon('play')}<span>${t('环球巡航','World tour')}</span></button>`;
 const stop=tourStops[tour.index];
 return `<div class="tour-controls" data-tour-index="${tour.index}" data-playing="${tour.playing}"><span class="tour-status" role="status">${String(tour.index+1).padStart(2,'0')} / 05 · ${t(tour.playing?'巡航中':'已暂停',tour.playing?'Playing':'Paused')}</span><div class="tour-stops" aria-label="${t('巡航路线','Tour itinerary')}">${tourStops.map((s,i)=>`<button id="tour-stop-${i}" data-tour="stop" data-stop="${i}" aria-label="${i+1}. ${tr(layerById[s.layer].name)}" aria-current="${i===tour.index?'step':'false'}" title="${tr(layerById[s.layer].name)}"><span></span></button>`).join('')}</div><button id="tour-previous" data-tour="previous" aria-label="${t('上一站','Previous stop')}" ${tour.index===0?'disabled':''}>${icon('previous')}</button><button id="tour-toggle" data-tour="toggle" aria-label="${t(tour.playing?'暂停巡航':tour.index===4?'重新巡航':'继续巡航',tour.playing?'Pause tour':tour.index===4?'Restart tour':'Resume tour')}" aria-pressed="${tour.playing}">${icon(tour.playing?'pause':'play')}</button><button id="tour-next" data-tour="next" aria-label="${t('下一站','Next stop')}" ${tour.index===4?'disabled':''}>${icon('next')}</button><button class="tour-panel-jump" data-tour="panel">${t('面板','Panel')} ↓</button><button id="tour-exit" data-tour="exit" aria-label="${t('退出巡航并恢复原视角','Exit tour and restore workspace')}" title="${t('退出并恢复原视角（Esc）','Exit and restore workspace (Esc)')}">${icon('close')}</button></div><span class="tour-note" role="status">${tr(stop.note)}</span>`;
}
function bindTourControls(){document.querySelectorAll<HTMLElement>('[data-tour]').forEach(el=>el.onclick=()=>{const key=el.dataset.tour;if(key==='start'){void startTour();return;}if(key==='exit'){exitTour();return;}if(key==='toggle')tour.toggle();if(key==='next')tour.go(tour.index+1);if(key==='previous')tour.go(tour.index-1);if(key==='stop')tour.go(Number(el.dataset.stop));if(key==='panel'){tour.pause();document.querySelector('.right-panel')?.scrollIntoView({behavior:'instant'});}document.getElementById(el.id)?.focus({preventScroll:true});});}
function updateTourControls(){const dock=document.querySelector('#tour-dock');if(!dock)return;const focused=document.activeElement?.id;dock.innerHTML=tourControls();bindTourControls();if(focused?.startsWith('tour-'))document.getElementById(focused)?.focus({preventScroll:true});}
async function startTour(){if(state.focus)await exitMapFullscreen();if(tour.active)return;beforeTour={workspace:tourWorkspace(),camera:scene?.camera()??savedCamera,solo:soloSaved?[...soloSaved]:null};soloSaved=null;tour.start(!tourMotion.matches);document.querySelector<HTMLElement>('#tour-toggle')?.focus({preventScroll:true});}
function showTourStop(index:number){
 const stop=tourStops[index];state.active=[...presets.overview.layers];state.hidden=state.active.filter(id=>!isArea(id)&&id!==stop.layer);state.primary='developers';state.inspect=stop.layer;state.entity=null;state.entityTabs=[];state.selected='';state.preset='overview';state.view=stop.view;state.mobile='map';
 render();const anchor=stop.anchor?pointIndex[stop.layer].find(p=>p.id===stop.anchor):undefined;
 if(anchor?.longitude!=null&&anchor.latitude!=null)scene?.locate(anchor.longitude,anchor.latitude,1.05);else scene?.reset();
}
function exitTour(rerender=true){tour.stop();if(beforeTour){Object.assign(state,beforeTour.workspace);scene?.destroy();scene=null;savedCamera=beforeTour.camera;soloSaved=beforeTour.solo;beforeTour=undefined;}if(rerender){render();document.querySelector<HTMLElement>('#tour-start')?.focus({preventScroll:true});}}
app.addEventListener('click',e=>{if(tour.active&&!(e.target as Element).closest('[data-tour]'))tour.pause();},true);
app.addEventListener('change',()=>{if(tour.active)tour.pause();},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&tour.active)tour.pause();});
tourMotion.addEventListener('change',()=>{if(tourMotion.matches&&tour.active)tour.pause();});

function render(){if(!state.entity&&(!state.inspect||!state.active.includes(state.inspect)))state.inspect=state.primary??state.active[0]??null;if(!state.inspect&&state.entityTabs.length){state.entity=state.entityTabs.at(-1)!;state.inspect=state.entity.overlayId;}disposePulse?.();disposePulse=undefined;disposeRadar?.();disposeRadar=undefined;disposeGalaxy?.();disposeGalaxy=undefined;const pageScroll=window.scrollY,tabScroll=document.querySelector('.inspector-tabs')?.scrollLeft??0;const focus=document.activeElement?.id,leftScroll=document.querySelector('.tree-scroll')?.scrollTop??0,compareScroll=document.querySelector('.comparison-rows')?.scrollTop??0,stackScroll=document.querySelector('.stack-list')?.scrollTop??0;const camera=scene?.camera()??savedCamera;if(camera)savedCamera=camera;scene?.destroy();scene=null;document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.documentElement.dataset.theme=state.light?'light':'dark';const favicon=document.querySelector<HTMLLinkElement>('link[rel=icon]');if(favicon)favicon.href=`${import.meta.env.BASE_URL}brand/opendipper/opendipper-small-${state.light?'light':'dark'}.svg`;
app.innerHTML=`<div class="shell ${tour.active&&state.page==='overview'?'touring':''} ${state.focus?'focus-mode':''} ${state.page!=='overview'?'portal-shell':''} ${state.page==='radar'?'radar-shell':''} ${state.page==='ecosystem'?'galaxy-shell':''} tab-${state.mobile} layout-${state.layout}">${header()}${state.page==='overview'?observatory():state.page==='radar'?radarPage(radarContext()):state.page==='ecosystem'?galaxyPage(galaxyContext()):portalPage(portalContext(),ecosystem(),state.page==='following'?radarFollowing(radarContext()):'')}</div>${state.page==='overview'&&state.layout==='two'?secondScreen():''}<div id="modal-root"></div><div id="toast" role="status"></div>`;
if(state.page==='overview'&&state.view!=='wire'){const id=state.primary;const base=regions.map(c=>({...c,atlasValue:id?pointIndex[id].find(p=>p.rawCode===c.rawCode)?.atlasValue:undefined}));scene=new Scene(document.querySelector('#earth')!,{mode:state.view as 'map'|'globe',countries:base,metric:'atlasValue',colorMetric:id??'developers',fillLabel:id?tr(layerById[id].metric):'',events:[],features:data.features,grid:state.grid,heat:!!id&&pointIndex[id].length>0,markers:false,eventMarkers:false,lang:state.lang,selected:state.selected,demo:false,light:state.light,texture:state.texture,overlays:overlayData(),onInteract:()=>{if(tour.active)tour.pause();}},selectPoint);if(camera)scene.restore(camera);}
const pulseRoot=document.querySelector<HTMLElement>('.pulse-panel');if(pulseRoot)disposePulse=mountPulse(pulseRoot,state.lang,dashboard,pulses=>{if(scene)scene.data.simulatedPulses=pulses;const badge=document.querySelector<HTMLElement>('.map-pulse-label');if(badge)badge.hidden=!pulses.length;},pulseEvent,pulseHelp);
bind();const tabstrip=document.querySelector('.inspector-tabs');if(tabstrip){tabstrip.scrollLeft=tabScroll;const tab=tabstrip.querySelector<HTMLElement>('.inspector-tab.active');if(tab){const a=tabstrip.getBoundingClientRect(),b=tab.getBoundingClientRect();if(b.left<a.left)tabstrip.scrollLeft-=a.left-b.left;else if(b.right>a.right)tabstrip.scrollLeft+=b.right-a.right;}}document.querySelector('.tree-scroll')?.scrollTo({top:leftScroll});document.querySelector('.stack-list')?.scrollTo({top:stackScroll});document.querySelector('.comparison-rows')?.scrollTo({top:compareScroll});if(focus)document.getElementById(focus)?.focus({preventScroll:true});window.scrollTo({top:pageScroll,behavior:'instant'});}
function overlayData():Overlay[]{return activePoints().map(id=>{if(isBubble(id))return {id,name:tr(layerById[id].name),color:layerColor(id),shape:'circle' as const,encoding:'bubble' as const,unit:tr(layerById[id].unit),maxValue:Math.max(0,...pointIndex[id].map(p=>p.atlasValue??0)),opacity:state.opacity[id],points:pointIndex[id]};const buckets=new Map<string,Point[]>();for(const p of pointIndex[id]){const key=`${p.longitude},${p.latitude}`;buckets.set(key,[...(buckets.get(key)??[]),p]);}const points=[...buckets.values()].map(ps=>ps.length===1?ps[0]:({...ps[0],clusterCount:ps.length,clusterIds:ps.map(p=>p.id!),entityName:[`${ps[0].countryZh??ps[0].country} · ${ps.length} ${layerById[id].name[0]}`,`${ps[0].country} · ${ps.length} ${layerById[id].name[1]}`] as [string,string]}));return {id,name:tr(layerById[id].name),color:layerColor(id),shape:'circle' as const,encoding:'entity' as const,opacity:state.opacity[id],points};});}
function openCluster(p:Point){modal(tr(p.entityName!),`<p>${t('同一城市参考点的实体，逐项查看。','Entities sharing a city reference, listed separately.')}</p><div class="modal-catalog">${pointIndex[p.overlayId].filter(x=>p.clusterIds?.includes(x.id!)).map(x=>`<button class="catalog-row" data-cluster-entity="${esc(x.id)}"><span>${esc(tr(x.entityName!))}</span>↗</button>`).join('')}</div>`);document.querySelectorAll<HTMLElement>('[data-cluster-entity]').forEach(el=>el.onclick=()=>inspectEntity(pointIndex[p.overlayId].find(x=>x.id===el.dataset.clusterEntity)!));}

function navigate(page:Page){if(tour.active)exitTour(false);state.page=page;state.focus=false;history.replaceState(null,'',`#${page}`);render();}
function toast(s:string){const e=document.querySelector('#toast')!;e.textContent=s;e.classList.add('visible');setTimeout(()=>e.classList.remove('visible'),3500);}
function project(path:string){const r=data.snapshot.repositories.find((r:any)=>r.path===path);if(!r)return;modal(path,`<p>${t('真实月度样本 · OpenRank','Observed monthly sample · OpenRank')}</p><div class="project-values">${r.metrics.openrank.points.slice(-12).map((p:any)=>`<div><span>${p.month}</span><b>${fmt(p.value)}</b></div>`).join('')}</div><button class="primary" id="watch-project">${watch.includes(r.key)?t('取消关注','Unfollow'):t('关注项目','Follow project')}</button>`);document.querySelector('#watch-project')!.addEventListener('click',()=>{watch=watch.includes(r.key)?watch.filter(x=>x!==r.key):[...watch,r.key];localStorage.setItem('od-review-watch',JSON.stringify(watch));project(path);});}
function bind(){
 bindTourControls();
 document.querySelectorAll<HTMLElement>('.map-tools button,.top-actions button,.stack-item button,.layer-info').forEach(el=>{if(!el.title&&el.getAttribute('aria-label'))el.title=el.getAttribute('aria-label')!;});
 document.querySelectorAll<HTMLElement>('[data-latest-tab]').forEach(el=>{el.onclick=()=>{state.latestTab=el.dataset.latestTab as 'news'|'meetings';render();};el.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();state.latestTab=e.key==='Home'?'news':e.key==='End'?'meetings':state.latestTab==='news'?'meetings':'news';render();document.querySelector<HTMLElement>(`[data-latest-tab="${state.latestTab}"]`)?.focus();}};});
 document.querySelectorAll<HTMLElement>('[data-meeting]').forEach(el=>el.onclick=()=>{const p=pointIndex.meetings.find(p=>p.id===el.dataset.meeting);if(p)entityInfo(p);});
 document.querySelector('#legend-toggle')?.addEventListener('click',()=>{state.legendOpen=!state.legendOpen;const box=document.querySelector('.map-legend')!;box.classList.toggle('expanded',state.legendOpen);box.classList.toggle('collapsed',!state.legendOpen);const body=document.querySelector<HTMLElement>('#legend-content')!;body.hidden=!state.legendOpen;const toggle=document.querySelector('#legend-toggle')!;toggle.setAttribute('aria-expanded',String(state.legendOpen));toggle.querySelector('i')!.textContent=state.legendOpen?'⌄':'⌃';});
 document.querySelectorAll<HTMLElement>('[data-observation-tab]').forEach(el=>{el.onclick=()=>activateTab(el.dataset.observationTab!);el.onkeydown=e=>{const keys=['ArrowLeft','ArrowRight','Home','End','Delete'];if(!keys.includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll<HTMLElement>('[data-observation-tab]')];const i=tabs.indexOf(el),j=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowLeft'?-1:1)+tabs.length)%tabs.length;if(e.key==='Delete'){closeTab(el.dataset.observationTab!);document.querySelector<HTMLElement>('[role=tab][aria-selected=true]')?.focus({preventScroll:true});}else{const key=tabs[j].dataset.observationTab!;activateTab(key);document.querySelector<HTMLElement>('[role=tab][aria-selected=true]')?.focus({preventScroll:true});}};});
 document.querySelectorAll<HTMLElement>('[data-close-tab]').forEach(el=>el.onclick=()=>closeTab(el.dataset.closeTab!));
 document.querySelectorAll<HTMLElement>('[data-rank-key]').forEach(el=>el.onclick=()=>{const id=el.dataset.rankLayer as LayerId,r=rankingRows(id,data).find(r=>r.key===el.dataset.rankKey);if(r?.entity)inspectEntity(r.entity);else if(r?.region)focusCountry(r.region);});
 document.querySelectorAll<HTMLElement>('[data-back-layer]').forEach(el=>el.onclick=()=>{const id=el.dataset.backLayer as LayerId;if(!state.active.includes(id))state.active=toggleLayer(state.active,id);inspectLayer(id);});
 document.querySelector('[data-entity-evidence]')?.addEventListener('click',()=>{if(state.entity)entityInfo(state.entity);});
 document.querySelector('[data-locate-tab]')?.addEventListener('click',()=>{const p=state.entity!;if(!isBubble(p.overlayId)&&!state.active.includes(p.overlayId))state.active=toggleLayer(state.active,p.overlayId);state.hidden=state.hidden.filter(id=>id!==p.overlayId);state.selected=regionGroup(p.rawCode);state.mobile='map';render();scene?.locate(p.longitude!,p.latitude!,2.5);});
 document.querySelectorAll<HTMLElement>('[data-layout]').forEach(el=>el.onclick=()=>{state.layout=el.dataset.layout!;state.focus=false;render();window.scrollTo({top:0,behavior:'instant'});});
 document.querySelectorAll<HTMLElement>('[data-scroll-screen]').forEach(el=>el.onclick=()=>document.querySelector(el.dataset.scrollScreen==='2'?'#screen-two':'.shell')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 document.querySelectorAll<HTMLElement>('[data-open-catalog]').forEach(el=>el.onclick=()=>openCatalog(el.dataset.openCatalog as LayerId));
 const cl=document.querySelector<HTMLSelectElement>('#catalog-layer');if(cl)cl.onchange=()=>{state.catalog=cl.value as LayerId;state.catalogQuery='';render();};
 const cq=document.querySelector<HTMLInputElement>('#catalog-query');if(cq)cq.oninput=()=>{const pos=cq.selectionStart;state.catalogQuery=cq.value;render();const n=document.querySelector<HTMLInputElement>('#catalog-query')!;n.focus({preventScroll:true});n.setSelectionRange(pos,pos);};

 document.querySelectorAll<HTMLElement>('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action!));
 document.querySelectorAll<HTMLElement>('[data-page]').forEach(el=>el.onclick=e=>{e.preventDefault();navigate(el.dataset.page as Page);});
 const pa:PortalActions={navigate,render,modal,savePreferences:p=>{preferences=p;remember('od:intelligence',p);},filter:(topic,query)=>{state.topic=topic;state.portalQuery=query;render();},map:s=>{navigate('overview');if(s.location)scene?.locate(s.location.lon,s.location.lat,1.6);},project,toggleDemo:v=>{preferences.demo=v;remember('od:intelligence',preferences);render();},toast};
 if(state.page==='ecosystem')disposeGalaxy=mountGalaxy(document.querySelector('.galaxy-page')!,galaxyContext(),{modal,toast});
 else if(state.page==='radar')disposeRadar=bindRadar(radarContext(),{render,modal,toast,navigate,openSignal:s=>openSignal(portalContext(),pa,s),openGalaxy:url=>{locateGalaxy(url);navigate('ecosystem');}});
 else if(state.page!=='overview')bindPortal(portalContext(),pa);
 document.querySelectorAll<HTMLElement>('[data-radar-open]').forEach(el=>el.onclick=()=>{selectRadarEntity(el.dataset.radarOpen!);navigate('radar');});
 document.querySelectorAll<HTMLElement>('[data-project]').forEach(el=>el.onclick=()=>project(el.dataset.project!));
 document.querySelectorAll<HTMLElement>('[data-supply-metric]').forEach(el=>el.onclick=()=>{state.supplyMetric=el.dataset.supplyMetric as 'models'|'datasets';render();});
 document.querySelectorAll<HTMLElement>('[data-supply-month]').forEach(el=>el.onclick=()=>{state.supplyMonth=el.dataset.supplyMonth!;render();});
 document.querySelectorAll<HTMLElement>('[data-evidence]').forEach(el=>el.onclick=sources);
 document.querySelectorAll<HTMLInputElement>('[data-layer]').forEach(el=>el.onchange=()=>changeActive(toggleLayer(state.active,el.dataset.layer as LayerId)));
 document.querySelectorAll<HTMLInputElement>('[data-group]').forEach(el=>{const g=groups.find(g=>g.id===el.dataset.group)!;el.indeterminate=groupState(g.children,state.active)==='mixed';el.onchange=()=>changeActive(toggleGroup(state.active,g.children));});
 document.querySelectorAll<HTMLElement>('[data-fold]').forEach(el=>el.onclick=()=>{const id=el.dataset.fold!;state.collapsed.has(id)?state.collapsed.delete(id):state.collapsed.add(id);render();});
 document.querySelectorAll<HTMLElement>('[data-info]').forEach(el=>el.onclick=()=>layerInfo(el.dataset.info as LayerId));
 document.querySelectorAll<HTMLElement>('[data-inspect]').forEach(el=>el.onclick=()=>inspectLayer(el.dataset.inspect as LayerId));
 document.querySelectorAll<HTMLElement>('[data-entity]').forEach(el=>el.onclick=()=>{const p=Object.values(pointIndex).flat().find(p=>p.id===el.dataset.entity);if(p)inspectEntity(p);});
 document.querySelectorAll<HTMLElement>('[data-region]').forEach(el=>el.onclick=()=>{const c=regions.find(c=>c.rawCode===el.dataset.region);if(c){if(el.dataset.catalogRegion){const id=el.dataset.catalogRegion as LayerId;if(!state.active.includes(id))state.active=toggleLayer(state.active,id);if(isArea(id))state.primary=id;state.inspect=id;}focusCountry(c);if(el.dataset.catalogRegion)window.scrollTo({top:0,behavior:'instant'});}});
 document.querySelectorAll<HTMLElement>('[data-view]').forEach(el=>el.onclick=()=>{state.view=el.dataset.view!;state.page='overview';state.mobile='map';render();});
 document.querySelectorAll<HTMLElement>('[data-mobile]').forEach(el=>el.onclick=()=>{state.mobile=el.dataset.mobile!;render();});
 const perspective=document.querySelector<HTMLSelectElement>('#perspective');if(perspective)perspective.onchange=()=>applyPreset(perspective.value);
 const search=document.querySelector<HTMLInputElement>('#layer-search');if(search)search.oninput=()=>{const pos=search.selectionStart;state.layerSearch=search.value;render();const next=document.querySelector<HTMLInputElement>('#layer-search')!;next.focus();next.setSelectionRange(pos,pos);};
 const primary=document.querySelector<HTMLSelectElement>('#primary-layer');if(primary)primary.onchange=()=>inspectLayer(primary.value as LayerId);
 document.querySelector('#clear-layers')?.addEventListener('click',()=>changeActive([]));
 document.querySelector('#clear-region')?.addEventListener('click',()=>{state.selected='';state.entity=null;render();});
 document.querySelectorAll<HTMLElement>('[data-eye]').forEach(el=>el.onclick=()=>{state.hidden=toggleLayer(state.hidden,el.dataset.eye as LayerId);soloSaved=null;render();});
 document.querySelectorAll<HTMLElement>('[data-up]').forEach(el=>el.onclick=()=>{state.active=moveLayer(state.active,el.dataset.up as LayerId,1);render();});
 document.querySelectorAll<HTMLElement>('[data-solo]').forEach(el=>el.onclick=()=>{const id=el.dataset.solo as LayerId;if(soloSaved){state.hidden=soloSaved;soloSaved=null;}else{soloSaved=[...state.hidden];state.hidden=state.active.filter(x=>!isArea(x)&&x!==id);}render();});
 document.querySelectorAll<HTMLInputElement>('[data-opacity]').forEach(el=>el.oninput=()=>{const id=el.dataset.opacity as LayerId;state.opacity[id]=Number(el.value)/100;el.closest('label')!.querySelector('output')!.textContent=`${el.value}%`;if(scene)scene.data.overlays=overlayData();});
 document.querySelectorAll<HTMLElement>('[data-zone]').forEach(el=>el.onclick=()=>{state.selected='';state.entity=null;render();const zs:Record<string,number[]>={asia:[105,28],europe:[15,49],americas:[-90,29],africa:[22,2]};if(el.dataset.zone==='world')scene?.reset();else{const [x,y]=zs[el.dataset.zone!];scene?.locate(x,y,1.6);}});
 document.querySelectorAll<HTMLElement>('[data-event]').forEach(el=>el.onclick=()=>openEvent(actualEvents().find(e=>e.id===el.dataset.event)!));
 const q=document.querySelector<HTMLInputElement>('#wire-query');if(q)q.oninput=()=>{state.query=q.value;const pos=q.selectionStart;render();const el=document.querySelector<HTMLInputElement>('#wire-query')!;el.focus();el.setSelectionRange(pos,pos);};
}
function action(id:string){if(id==='clear-region'){state.selected='';state.entity=null;render();return;}if(id==='fullscreen'){void toggleFullscreen();return;}if(id==='sources')sources();if(id==='help')help();if(id==='language'){state.lang=state.lang==='zh'?'en':'zh';try{localStorage.setItem('od:atlas-lang',state.lang);}catch{}render();}if(id==='theme'){state.light=!state.light;remember('od:light',state.light);render();}if(id==='map-fullscreen'){void toggleMapFullscreen();return;}if(id==='regions')regionPicker();if(id==='zoom-in')scene?.scale(.3);if(id==='zoom-out')scene?.scale(-.3);if(id==='reset'){state.selected='';state.entity=null;render();scene?.reset();}if(id==='grid'){state.grid=!state.grid;render();}if(id==='rotate')scene?.spin();}
function modal(title:string,body:string){if(tour.active)tour.pause();const returnTo=document.activeElement as HTMLElement;const root=document.querySelector('#modal-root')!;root.innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1" class="modal"><header><div><h2>${esc(title)}</h2></div><button id="close-modal" aria-label="${t('关闭','Close')}">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;const close=()=>{root.replaceChildren();if(returnTo?.isConnected)returnTo.focus();};root.querySelector('#close-modal')!.addEventListener('click',close);root.querySelector('.modal-backdrop')!.addEventListener('click',e=>{if(e.target===e.currentTarget)close();});const dialog=root.querySelector<HTMLElement>('.modal')!;dialog.focus();dialog.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();close();}if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll<HTMLElement>('button,a[href],input,select')];const a=nodes[0],b=nodes.at(-1);if(e.shiftKey&&(document.activeElement===a||document.activeElement===dialog)){b?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===b){a?.focus();e.preventDefault();}}};}
function regionPicker(){modal(t('查找地域','Find a region'),`<div class="region-search">${icon('search')}<input id="region-query" aria-label="${t('地域名称或代码','Region name or code')}" placeholder="${t('搜索中国、美国、法国或地域代码','Search China, France or a region code')}"/></div><p class="dialog-note">${t('选择地域后，对照已选图层；缺少观测值时保留空缺。','Select a region to compare active layers. Missing observations remain missing.')}</p><div id="region-results"></div>`);const input=document.querySelector<HTMLInputElement>('#region-query')!;function list(){const q=input.value.toLowerCase();const all=regions.filter(c=>`${countryName(c,state.lang)} ${c.country} ${c.rawCode} ${c.sourceCode}`.toLowerCase().includes(q));all.sort((a,b)=>(b.atlasValue??0)-(a.atlasValue??0));document.querySelector('#region-results')!.innerHTML=all.slice(0,60).map(c=>`<button data-region="${c.rawCode}"><span>${esc(countryName(c,state.lang))}</span><small>${c.rawCode}</small>${icon('arrow')}</button>`).join('')||`<p>${t('没有匹配地域','No matching region')}</p>`;document.querySelectorAll<HTMLElement>('[data-region]').forEach(el=>el.onclick=()=>focusCountry(regions.find(c=>c.rawCode===el.dataset.region)!));}input.oninput=list;list();input.focus();}
function openEvent(e:Event){if(!e)return;modal(state.lang==='en'?e.titleEn??e.title:e.title,`<div class="event-source">${esc(e.source)} · ${esc(new Date(e.occurredAt).toLocaleString(state.lang==='zh'?'zh-CN':'en-GB'))}</div><p>${esc(state.lang==='en'?e.summaryEn??e.summary:e.summary)}</p><p>${icon('pin')} ${e.location?esc(locationName(e.location,state.lang)):t('全球／尚未定位','Global / unlocated')}</p><a class="primary" href="${esc(safeUrl(e.sourceUrl))}" target="_blank" rel="noopener">${t('阅读原始来源','Read original source')} ↗</a>`);}
function layerInfo(id:LayerId){const l=layerById[id];modal(tr(l.name),`<div class="layer-dialog-title">${symbol(id)}<strong>${pointIndex[id].length}</strong><span>${isRegional(id)?t('地域统计条目','regional records'):t('可定位实体','located entities')}</span>${l.demo?'<span class="demo-tag">DEMO</span>':''}</div><p>${esc(sourceText(id,state.lang,data))}</p><p>${isArea(id)?t('地域色块使用独立对数色阶。开发者组至多选一项，可全部取消。地图一次展示一个主色阶；资产气泡和实体点可叠加。','Each area metric uses its own logarithmic scale. Developer selections are optional and exclusive. Use one fill at a time; asset bubbles and entity points overlay it.'):isBubble(id)?t('气泡面积与地域资产数量成正比；圆心是地域汇总参考点，不是仓库或设施地址。资产组至多选一项，也可全不选。缺少地域数据时不绘制气泡。','Bubble area is proportional to regional asset count. Centers are regional references, not repository or facility addresses. Asset selection is optional and exclusive; missing regional data produces no bubbles.'):t('圆点表示单个实体，颜色区分类别。环状纹理用于辨识图层，不表示数值；缺少地点证据时不放置点位。','Circles represent entities; color and ring patterns identify categories, not magnitude. Records without location evidence are not placed.')}</p>${id==='news'?`<p>${actualEvents().length} ${t('条已采集内容；','collected items; ')}${pointIndex.news.length} ${t('条已有定位','located items')}</p>`:''}<button class="primary" id="info-toggle">${state.active.includes(id)?t('取消选择','Deselect layer'):t('加入观察','Select layer')}</button>`);document.querySelector('#info-toggle')!.addEventListener('click',()=>changeActive(toggleLayer(state.active,id)));}
function entityInfo(p:Point){if(p.event){openEvent(p.event);return;}modal(tr(p.entityName??[p.country,p.country]),`<p>${esc(tr(p.locationRole??layerById[p.overlayId].metric))} · ${esc(countryName(p,state.lang))}</p><div class="entity-coordinates">${p.longitude!=null&&p.latitude!=null?`${p.longitude.toFixed(2)}°, ${p.latitude.toFixed(2)}°`:t('位置待核验','Location unverified')}</div><p>${p.precision?esc(tr(p.precision)):''}</p><p>${p.period?esc(tr(p.period)):''}</p><div class="entity-metrics">${p.metrics?.map(([k,v])=>`<div><span>${esc(metricName(k))}</span><b>${typeof v==='number'?fmt(v):esc(v)}</b></div>`).join('')??''}</div><p>${p.note?esc(tr(p.note)):esc(sourceText(p.overlayId,state.lang,data))}</p><div class="entity-sources">${p.sourceUrls?.filter(Boolean).map((u,i)=>`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener">${t('证据','Evidence')} ${i+1} · ${esc(new URL(safeUrl(u)).hostname)} ↗</a>`).join('')??''}</div><button class="primary" id="locate-entity" ${p.longitude==null||p.latitude==null?'disabled':''}>${t('定位此实体','Locate entity')}</button>`);document.querySelector('#locate-entity')!.addEventListener('click',()=>{state.entity=p;state.inspect=p.overlayId;if(p.id&&!state.entityTabs.some(x=>x.id===p.id&&x.overlayId===p.overlayId))state.entityTabs.push(p);if(!state.active.includes(p.overlayId))state.active=toggleLayer(state.active,p.overlayId);state.hidden=state.hidden.filter(id=>id!==p.overlayId);state.selected=regionGroup(p.rawCode);state.mobile='map';render();window.scrollTo({top:0,behavior:'instant'});scene?.locate(p.longitude!,p.latitude!,2.5);});}

function help(){modal(t('全球观测 · 使用指南','Observatory · how to use'),`<p>${t('拖拽移动，滚轮缩放；点击地域或实体圆点，在右侧查看指标与来源。展开地图后按 Esc 返回。','Drag to move, scroll to zoom; select a region or circular marker to inspect its metrics and sources. Press Escape to return from the expanded map.')}</p><div class="help-steps"><div><b>01</b><h3>${t('选择观察对象','Select subjects')}</h3><p>${t('六类、十八层。地域色块用于规模、贡献与影响；资产气泡用面积表示数量；实体圆点用于有地点证据的组织、项目、设施与动态。','Six groups and eighteen layers. Areas show regional magnitude; bubble area encodes asset quantity; entity points locate organizations, projects, facilities and events.')}</p></div><div><b>02</b><h3>${t('一种色块、一种气泡、多种实体','One fill, one bubble layer, multiple entities')}</h3><p>${t('开发者组、资产组各自至多选一项，再次点击即可取消。不同面指标用主色阶切换；资产气泡和实体点可以共同叠加，支持透明度、隐藏和独显。','Developer and asset groups allow zero or one selection; click again to deselect. Switch between area fills, and overlay bubbles and entity points with opacity, visibility and isolation controls.')}</p></div><div><b>03</b><h3>${t('分别计量，按对象展开','Inspect separate measures')}</h3><p>${t('全球概览固定。每个已选图层、每个打开的实体都有独立标签。项目与资产采用排行榜；全球排名不会因地域选择改变。可用左右方向键切换标签、Delete 关闭标签，不同口径分别计量。','Global coverage stays fixed. Each selected layer and opened entity has its own tab. Project and asset rankings retain their global scope. Use arrow keys to switch tabs and Delete to close. Different measures remain separate.')}</p></div></div><p>${t('项目点位按关联组织或发布方归属，不代表历史发起地、训练或部署地点。未定位原表条目保留在第二屏清单。','Project points use associated organizations or publishers, not historical origin, training or deployment. Unlocated report records remain in the second-screen catalog.')}</p>`);}
function pulseHelp(){modal(t('生态脉动 · 基数与模拟增量','Ecosystem pulse · baselines & simulated increments'),`<p>${t('每 2.2 秒刷新一次演示增量。数字增长、事件、位置关联、平台活跃条和趋势均为模拟，尚未接入实时采集。大数字是下列基数加演示增量，并不回写真实地图、排行榜或全球概览。','Illustrative increments refresh every 2.2 seconds. Growth, events, geographic attribution, platform bars and trends are simulated; live ingestion is not connected. Counters add demo growth to the baselines below without modifying actual map metrics, rankings or the overview.')}</p><div class="source-block"><h3>${t('活跃开发者','Active developers')}</h3><p>${fmt(dashboard.upstream.summary.activeDevelopers)} · GitHub · 2025.07—2026.06。${t('报告基数 2,890.36 万；后续增长为模拟。','Report baseline of 28.90M; subsequent growth is synthetic.')}</p></div><div class="source-block"><h3>${t('Git 事件 · 提交量推演','Git events · commit scenario')}</h3><p>${t('2025 年 Git 提交量突破 10 亿、2026 年预计 140 亿，为项目方提供的规划口径，尚未独立核验。主数将 140 亿年度预测按自然年均匀分配至本次更新日，再叠加演示增量；既不是实测累计，也不代表所有 Git 事件类型。不据此计算精确同比增幅。','The project-provided assumptions (>1B commits in 2025, projected 14B in 2026) are not independently verified. The counter linearly allocates the annual forecast to this review date, then adds demo increments. It is neither an observed cumulative total nor all Git event types; no exact year-on-year growth is inferred.')}</p></div><div class="source-block"><h3>${t('活跃仓库 · 代码 / 模型 / 数据','Active repositories · code / models / data')}</h3><p>${fmt(dashboard.activeRepositories.value)} · ${tr(dashboard.activeRepositories.scope)} ${t('模型 72,280、数据集 12,291 为累计发布样本，不并入活跃基数。演示增量模拟三类仓库的后续活动，不是实际新增仓库。','The 72,280 model and 12,291 dataset publication samples are not active counts and are excluded. Demo increments illustrate future activity across all three repository types, not actual new repositories.')}</p></div><div class="source-block"><h3>${t('实时资讯','Live intelligence')}</h3><p>${t('从 12,840 条模拟规模起步，演示资讯汇入。右侧新闻与活动则使用现有采集快照，保留原始日期，两者不混合。','Starts from an illustrative inventory of 12,840 to demonstrate ingestion. The right-hand news/event tabs use existing sourced snapshots with original dates; they remain separate.')}</p></div><p>${t('七个信息源的数字为最近 60 秒的模拟参与者；arXiv 展示研究动态。可暂停、逐条推进、切换倍速或关闭地图联动；减少动态时暂停自动播放，后台或不可见时停止推进。','The seven sources show simulated participants over 60 seconds; arXiv illustrates research activity. Pause, step, change speed or disable map pulses; reduced motion pauses playback and hidden/offscreen views stop advancing.')}</p>`);}
function pulseEvent(e:PulseEvent){modal(t('模拟事件','Simulated event'),`<span class="simulation-badge">${t('模拟演示 · 非实时数据','SIMULATION · NOT LIVE DATA')}</span><h3 class="pulse-detail-title">${esc(e.place[state.lang==='zh'?0:1])} · ${esc(e.platform)}</h3><div class="pulse-detail-value">+${e.quantity} <span>${pulseLabels[e.kind][state.lang==='zh'?0:1]}</span></div><p>${t('仅为演示全球事件与地图的联动效果，事件及地点关联均为模拟。已暂停播放，关闭后可继续。','This illustrates the interaction between global events and the map. Both events and place attribution are synthetic. Playback is paused; resume when ready.')}</p><button class="primary" id="locate-pulse">${t('定位演示地点','Locate demo place')}</button>`);document.querySelector('#locate-pulse')!.addEventListener('click',()=>{document.querySelector('#modal-root')!.replaceChildren();state.mobile='map';if(window.innerWidth<=700)render();scene?.locate(e.longitude,e.latitude,1.3);});}
function sources(){modal(t('数据与来源','Data & sources'),`<p>${t('各指标按独立周期更新；新闻使用已发布采集快照，生态脉动为模拟。来源集中展示，保留统计期、样本范围与缺口。','Measures update independently. News uses published collection snapshots; the pulse is simulated. Centralized evidence retains each period, scope and gap.')}</p><div class="source-block"><h3>GOSD 2026 · ${t('地域观测','Regional observations')}</h3>${layers.filter(l=>isRegional(l.id)).map(l=>`<p><b>${tr(l.name)}</b> · ${tr(l.scope)}<br>${esc(sourceText(l.id,state.lang,data))} <a href="${esc(l.id==='developers'?data.activeDevelopers.source.url:data.report.areas[l.id].sourceUrl)}" target="_blank" rel="noopener">${t('图件','Figure')} ↗</a></p>`).join('')}</div><div class="source-block"><h3>${t('代码资产 · 月度仓库榜','Code assets · monthly repository ranking')}</h3><p>${esc(tr(data.repoRanking.note))}</p><a href="${esc(data.repoRanking.sourceUrl)}" target="_blank" rel="noopener">2026.09 · OpenShare ↗</a> · <a href="${esc(data.repoRanking.dataUrl)}" target="_blank" rel="noopener">${t('公开数据快照','Public snapshot')} ↗</a></div><div class="source-block"><h3>${t('组织、项目与位置','Organizations, projects & locations')}</h3><p>${t('企业、基金会、标杆项目、新势力项目、大模型项目采用报告第三章原表，排除模拟补位。当前已核验位置只是原表子集。高校与科研采用官方联系页样本；项目关联至组织总部，模型关联至发布方总部，均不表示历史发起地、训练或部署地点。','Chapter 3 original tables supply companies, foundations, benchmark projects, emerging projects and model versions; simulated extensions are excluded. Located entries are a subset. Universities use official contact pages. Project and model points refer to associated organizations, not historical origin, training or deployment.')}</p><a href="https://www.x-lab.info/2026-Global-Open-Source-Development-Report/2026/zh/chapters/03/" target="_blank" rel="noopener">${t('报告第三章','Report chapter 3')} ↗</a></div><div class="source-block"><h3>${t('基础设施与动态','Infrastructure & events')}</h3><p>${t('能源：WRI Global Power Plant Database 仓库快照的 12 座历史设施样本，各指定地域取原表最大容量记录。数据已停止维护，不表示当前在运状态或对 AI 设施的供电关系。原始经纬度、容量、源表与 SHA-256 保留。数据许可：CC BY 4.0。','Energy: 12 historical records from WRI Global Power Plant Database repository snapshot, selecting the highest-capacity record in each named region. The dataset is no longer maintained; records do not establish current operation or supply to AI facilities. Original coordinates, capacity, source records and SHA-256 are retained. Data license: CC BY 4.0.')}</p><a href="https://github.com/wri/global-power-plant-database" target="_blank" rel="noopener">WRI ↗</a><p>${t('算力：LUMI、JUPITER 官方位置；活动：Linux Foundation 主办方日程。新闻保留原发布时间，有地点证据才入图。每条实体详情均可查阅证据链接、位置角色与坐标精度。','Compute: official LUMI and JUPITER locations. Conferences: Linux Foundation organizer schedules. News retains its original publication date and requires location evidence for mapping. Entity details expose evidence, location role and coordinate precision.')}</p></div><div class="source-block"><h3>${t('全球概览与数据更新','Global coverage & update dates')}</h3><p>${t('前四项来自 OpenShare GOSD 同源元数据：地域覆盖、开发者、仓库、日志。246 是上游覆盖值，和地图已收录的 239 条地域观测不是同一口径。资讯总量 12,840 为模拟规模，当前实际采集快照为','The first four totals use OpenShare GOSD metadata: regions, developers, repositories and logs. Upstream coverage of 246 is distinct from the map’s 239 regional records. Intelligence inventory 12,840 is simulated; the collected snapshot contains')} ${actualEvents().length} ${t('条。','records.')}</p><p>${t('顶部“数据更新”表示本页核对与整理日期','The top “Updated” date is this page’s verification date')}: ${dashboard.checkedAt}。${t('上游原始快照更新','Original source snapshot')}: ${dashboard.upstream.summary.updatedAt.slice(0,10)}。${t('统计期','Period')}: 2025.07—2026.06。</p><a href="${dashboard.upstream.pageUrl}" target="_blank" rel="noopener">OpenShare GOSD ↗</a> · <a href="${dashboard.upstream.url}" target="_blank" rel="noopener">${t('原始元数据','Source metadata')} ↗</a><p>${t('生态脉动以报告基数、年度预测及模拟增量展示，未接入实时采集；点击动态指标或 ⓘ 查看完整口径。台湾是中国的一部分；中国实体筛选包含中国台湾，原始统计不自动相加。','The pulse combines report baselines, an annual forecast and simulated increments without live ingestion; its metric buttons and ⓘ explain all scopes. Taiwan is part of China; China entity filters include Taiwan without automatically summing source statistics.')}</p></div><p class="dialog-note">${t('沿用 OpenDipper 与 X-lab 品牌资产、Natural Earth 地理底图。保留应用、品牌与来源数据各自的许可边界。','Uses OpenDipper / X-lab brand assets and Natural Earth geography, retaining separate application, brand and data licenses.')}</p>`);}

async function start(){try{const names=['evidence.json','observation.json','events.json','countries.geojson','anchors.json','active-developers.json','snapshot.json','intelligence-demo.json','report-layers.json','located-entities.json','repo-ranking.json','dashboard-overview.json'];const raw=await Promise.all(names.map(async f=>{const r=await fetch(`${import.meta.env.BASE_URL}data/${f}`);if(!r.ok)throw Error(f);return r.json();}));dashboard=raw[11];data={evidence:raw[0],observation:raw[1],feed:raw[2],features:raw[3].features,anchors:raw[4].rows,activeDevelopers:raw[5],snapshot:raw[6],intelligence:raw[7],report:raw[8],located:raw[9],repoRanking:raw[10]};data.snapshot.repositories.forEach((r:any)=>r.key??=`${r.platform}:${r.path}`);regions=regionsFor(data);pointIndex=Object.fromEntries(layers.map(l=>[l.id,pointsFor(l.id,data)])) as Record<LayerId,Point[]>;const hash=location.hash.slice(1).split('?')[0];if(Object.hasOwn(pages,hash))state.page=hash as Page;render();await loadRadar(import.meta.env.BASE_URL);if(state.page==='radar'||state.page==='following')render();}catch(e){console.error(e);app.innerHTML='<div class="load-error"><h1>OpenDipper</h1><p>观测快照暂不可用 / Observation snapshot unavailable</p><button onclick="location.reload()">重试 / Retry</button></div>';}}
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&tour.active&&!document.querySelector('.modal')){e.preventDefault();exitTour();return;}if(e.key==='Escape'&&state.focus&&!document.querySelector('.modal')){e.preventDefault();void exitMapFullscreen();return;}if(state.page==='overview'&&(e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();regionPicker();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement)?.tagName)){e.preventDefault();document.querySelector<HTMLInputElement>('#layer-search')?.focus();}});window.addEventListener('pagehide',()=>{tour.stop();disposePulse?.();disposeRadar?.();disposeGalaxy?.();scene?.destroy();});void start();

// Recheck published news snapshots; failures retain the last valid feed and never advance source dates.
const eventRefresh=window.setInterval(async()=>{if(document.hidden||!data)return;try{const response=await fetch(`${import.meta.env.BASE_URL}data/events.json`,{cache:'no-cache'});if(!response.ok)return;const next=await response.json();if(!Array.isArray(next.events)||JSON.stringify(next)===JSON.stringify(data.feed))return;data.feed=next;pointIndex.news=pointsFor('news',data);if(!document.querySelector('.modal'))render();}catch{}},300000);
window.addEventListener('pagehide',()=>clearInterval(eventRefresh));
